/**
 * Utility to automatically scan and list video files
 * This creates a manifest of available videos in the public/video folder
 */

// Known video files - in production, this would be generated by a build script
// or fetched from a manifest.json file
const VIDEO_EXTENSIONS = ['.mp4']; // Only MP4 files are supported

/**
 * Generate a list of video files
 * In a real app, this would fetch from a manifest.json or API
 * For now, we'll maintain a list that can be updated
 */
export const getVideoFiles = async () => {
  try {
    // Try to fetch a manifest file first
    const response = await fetch('/video-manifest.json');
    if (response.ok) {
      const manifest = await response.json();
      // Only return MP4 files
      return (manifest.videos || []).filter(filename => filename.toLowerCase().endsWith('.mp4'));
    }
  } catch (error) {
    console.log('No manifest file found, using default list');
  }

  // Fallback: return known MP4 videos only
  return [
    '1564674844-disney.mp4',
    '1564676115-marvel.mp4',
    '1564676296-national-geographic.mp4',
    '1564676714-pixar.mp4',
    '1608229455-star-wars.mp4',
    'Jolly.LLB-3.2025.mp4'
  ];
};

/**
 * Check if a file is a video file based on extension
 */
export const isVideoFile = (filename) => {
  const lowerFilename = filename.toLowerCase();
  return VIDEO_EXTENSIONS.some(ext => lowerFilename.endsWith(ext));
};

/**
 * Generate a movie entry from a video filename
 */
export const generateMovieFromVideo = (filename, index) => {
  // Extract title from filename (remove extension and clean up)
  const nameWithoutExt = filename.replace(/\.[^/.]+$/, '');
  let cleanTitle = nameWithoutExt
    .replace(/[._-]/g, ' ')
    .replace(/\d{4}/g, '') // Remove years
    .replace(/720p|1080p|DS4K|WEB-DL|HDHub4u|Ms|mkv|mp4|ios|compatible/gi, '')
    .trim()
    .split(' ')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  // Special handling for Jolly LLB 3
  if (filename.includes('Jolly') || filename.includes('LLB')) {
    cleanTitle = 'Jolly LLB 3';
  }

  // Additional cleanup for Jolly LLB 3 specific patterns
  cleanTitle = cleanTitle.replace(/Jolly\.LLB-3\.2025/g, 'Jolly LLB 3');

  // All videos are now MP4 format

  return {
    id: `auto-${index}`,
    title: cleanTitle || `Movie ${index + 1}`,
    videoUrl: `/video/${filename}`,
    backgroundImg: "/images/jolly-llb-3-background.jpg",
    cardImg: "/images/jolly-llb-3-poster.jpg",
    description: `${cleanTitle} - A comedy-drama film about justice and law in India.`,
    subTitle: "2025 • 2h 15m • Comedy, Drama, Legal",
    titleImg: "/images/jolly-llb-3-title.png",
    type: "new",
    priority: 1 // All videos are now MP4
  };
};

